#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    int count = 0;
    char p = s[0];
    bool even = false;
    for (size_t i = 1; i < s.length(); ++i) {
        even = !even;
        if (i == s.length() - 1 && s[i] == p && even) {
            ++count;
        }
        if (s[i] != p) {
            p = s[i];
            count += !even ? 1 : 0;
            even = false;
        }
    }
    std::cout << count << std::endl;
    return 0;
}
